  app.querySelectorAll("[data-action^='install:'],[data-action^='start:'],[data-action^='stop:']").forEach((element) => element.addEventListener("click", async () => { const [operation, id] = element.dataset.action.split(":"); element.disabled = true; try { const plan = await api(`/api/instances/${id}/plans/${operation}`); const commands = plan.commands.map((item) => `${item.label}\n${item.command}`).join("\n\n"); if (!confirm(`Review ${operation} plan before applying:\n\n${commands}`)) { element.disabled = false; return; } const outcome = await api(`/api/instances/${id}/actions/${operation}`, { method: "POST" }); const unavailable = [...(outcome.prerequisites || []), ...(outcome.bridge ? [outcome.bridge] : [])].filter((item) => item.status === "unavailable"); if (unavailable.length) alert(`Server ${operation} completed, but optional components need attention:\n\n${unavailable.map((item) => `${item.component || "bridge"}: ${item.detail}`).join("\n")}`); await loadInstances(); renderInstances(); } catch (error) { alert(error.message); element.disabled = false; } }));
  app.querySelectorAll("[data-action^='preset:']").forEach((element) => element.addEventListener("click", async () => { const [, id, preset] = element.dataset.action.split(":"); try { await api(`/api/instances/${id}/preset`, { method: "POST", body: JSON.stringify({ preset }) }); alert(`${preset} preset applied live.`); } catch (error) { alert(error.message); } }));
