  const queueForm = controls ? `<form id="queue-form" class="toolbar">${mapFields}${button("Queue map", "queue-add", "primary")}</form>` : "";
  shell(`<div class="toolbar">${serverSelect()}${controls ? button("Skip to next", "next-map", "primary") : ""}${button("Export JSON", "export-rotation")}${importControl}</div><p class="muted">Panel-applied current map command: ${escapeHtml(state.rotation.expected_current_command || "not recorded yet")}</p><div class="grid"><article class="control-card"><h3>Persistent cycle</h3><p class="muted">Drag cards to reorder. This sequence repeats after one-time maps are consumed.</p><div class="rotation-list" id="rotation-list">${cards || "<span class='muted'>Rotation is empty.</span>"}</div>${cycleForm}</article><article class="control-card"><h3>One-time queue</h3><p class="muted">Queue a map for the next transition without changing the persistent cycle.</p><div class="rotation-list">${queue || "<span class='muted'>Queue is empty.</span>"}</div>${queueForm}</article></div><h3>Rotation history</h3><div class="stack">${historyCards || "<p class='muted'>No previous versions yet.</p>"}</div>`);
