  app.querySelector("#rotation-import")?.addEventListener("change", async (event) => { try { const payload = JSON.parse(await event.target.files[0].text()); await api(`/api/rotation/${instance.id}`, { method: "PUT", body: JSON.stringify(payload) }); renderRotation(); } catch (error) { alert(error.message); } });
